    /// <summary>Gets <c>shadow2Brand</c>.</summary>
    public required FluentShadow Shadow2Brand { get; init; }

    /// <summary>Gets <c>shadow4Brand</c>.</summary>
    public required FluentShadow Shadow4Brand { get; init; }

    /// <summary>Gets <c>shadow8Brand</c>.</summary>
    public required FluentShadow Shadow8Brand { get; init; }

    /// <summary>Gets <c>shadow16Brand</c>.</summary>
    public required FluentShadow Shadow16Brand { get; init; }

    /// <summary>Gets <c>shadow28Brand</c>.</summary>
    public required FluentShadow Shadow28Brand { get; init; }

    /// <summary>Gets <c>shadow64Brand</c>.</summary>
    public required FluentShadow Shadow64Brand { get; init; }

    /// <summary>
    /// Returns the shadows in the shadow colors of a theme (createShadowTokens).
    /// </summary>
    /// <param name="ambient">The color of the neutral ambient layer (colorNeutralShadowAmbient).</param>
    /// <param name="key">The color of the neutral key layer (colorNeutralShadowKey).</param>
    /// <param name="brandAmbient">The color of the brand ambient layer (colorBrandShadowAmbient).</param>
    /// <param name="brandKey">The color of the brand key layer (colorBrandShadowKey).</param>
    /// <returns>The shadows.</returns>
    internal static FluentShadows Create(Color ambient, Color key, Color brandAmbient, Color brandKey) =>
        new()
        {
            Shadow2 = new(new BoxShadow(ambient, new Vector2(0f, 0f), 2f), new BoxShadow(key, new Vector2(0f, 1f), 2f)),
            Shadow4 = new(new BoxShadow(ambient, new Vector2(0f, 0f), 2f), new BoxShadow(key, new Vector2(0f, 2f), 4f)),
            Shadow8 = new(new BoxShadow(ambient, new Vector2(0f, 0f), 2f), new BoxShadow(key, new Vector2(0f, 4f), 8f)),
            Shadow16 = new(new BoxShadow(ambient, new Vector2(0f, 0f), 2f), new BoxShadow(key, new Vector2(0f, 8f), 16f)),
            Shadow28 = new(new BoxShadow(ambient, new Vector2(0f, 0f), 8f), new BoxShadow(key, new Vector2(0f, 14f), 28f)),
            Shadow64 = new(new BoxShadow(ambient, new Vector2(0f, 0f), 8f), new BoxShadow(key, new Vector2(0f, 32f), 64f)),
            Shadow2Brand = new(new BoxShadow(brandAmbient, new Vector2(0f, 0f), 2f), new BoxShadow(brandKey, new Vector2(0f, 1f), 2f)),
            Shadow4Brand = new(new BoxShadow(brandAmbient, new Vector2(0f, 0f), 2f), new BoxShadow(brandKey, new Vector2(0f, 2f), 4f)),
            Shadow8Brand = new(new BoxShadow(brandAmbient, new Vector2(0f, 0f), 2f), new BoxShadow(brandKey, new Vector2(0f, 4f), 8f)),
            Shadow16Brand = new(new BoxShadow(brandAmbient, new Vector2(0f, 0f), 2f), new BoxShadow(brandKey, new Vector2(0f, 8f), 16f)),
            Shadow28Brand = new(new BoxShadow(brandAmbient, new Vector2(0f, 0f), 8f), new BoxShadow(brandKey, new Vector2(0f, 14f), 28f)),
            Shadow64Brand = new(new BoxShadow(brandAmbient, new Vector2(0f, 0f), 8f), new BoxShadow(brandKey, new Vector2(0f, 32f), 64f)),
        };
}

